INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Douglas Adams', 'Don''t panic.', 'Geen paniek.', 'Pas de panique.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Douglas Adams', 'The ships hung in the sky in much the same way that bricks don''t.', 'De schepen hingen in de lucht op vrijwel dezelfde manier als bakstenen dat niet doen.', 'Les vaisseaux pendaient dans le ciel à peu près de la même façon que les briques ne le font pas.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Douglas Adams', 'In the beginning the Universe was created. This has made a lot of people very angry and been widely regarded as a bad move.', 'In het begin werd het universum geschapen. Dit heeft veel mensen erg boos gemaakt en wordt algemeen beschouwd als een slechte zet.', 'Au commencement, l''Univers fut créé. Cela a mis beaucoup de monde très en colère et a été largement considéré comme une mauvaise idée.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Douglas Adams', 'There is an art, it says, or rather, a knack to flying. The knack lies in learning how to throw yourself at the ground and miss.', 'Er is een kunst, zegt het, of liever, een handigheidje om te vliegen. De truc is om te leren hoe je jezelf op de grond gooit en mist.', 'Il y a un art, est-il écrit, ou plutôt une astuce pour voler. L''astuce consiste à apprendre comment se jeter par terre et rater son coup.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Douglas Adams', 'I love deadlines. I love the whooshing noise they make as they go by.', 'Ik hou van deadlines. Ik hou van het zoevende geluid dat ze maken als ze voorbij vliegen.', 'J''adore les dates limites. J''adore le bruit de sifflement qu''elles font en passant.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Douglas Adams', 'Space is big. You just won''t believe how vastly, hugely, mind-bogglingly big it is. I mean, you may think it''s a long way down the road to the chemist''s, but that''s just peanuts to space.', 'De ruimte is groot. Je zult gewoon niet geloven hoe enorm, reusachtig, verbijsterend groot hij is. Ik bedoel, je denkt misschien dat het een heel eind lopen is naar de apotheek, maar dat is echt kinderspel vergeleken met de ruimte.', 'L''espace est grand. Vous n''imaginerez jamais à quel point c''est vaste, gigantesque, ahurissant. Je veux dire, vous pouvez penser que la pharmacie est loin au bout de la rue, mais c''est des cacahuètes comparé à l''espace.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Douglas Adams', 'A common mistake that people make when trying to design something completely foolproof is to underestimate the ingenuity of complete fools.', 'Een veelgemaakte fout die mensen maken wanneer ze iets volkomen hufterproof proberen te ontwerpen, is de vindingrijkheid van volkomen hufters te onderschatten.', 'Une erreur courante que font les gens lorsqu''ils essaient de concevoir quelque chose de totalement infaillible est de sous-estimer l''ingéniosité des imbéciles complets.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Douglas Adams', 'Time is an illusion. Lunchtime doubly so.', 'Tijd is een illusie. Lunchtijd des te meer.', 'Le temps est une illusion. L''heure du déjeuner doublement.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Douglas Adams', 'Anyone who is capable of getting themselves made President should on no account be allowed to do the job.', 'Iedereen die in staat is om zichzelf tot president te laten verkiezen, mag onder geen beding de baan doen.', 'Quiconque est capable de se faire élire Président ne devrait sous aucun prétexte être autorisé à exercer cette fonction.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Douglas Adams', 'There is a theory which states that if ever anyone discovers exactly what the Universe is for and why it is here, it will instantly disappear and be replaced by something even more bizarre and inexplicable. There is another theory which states that this has already happened.', 'Er is een theorie die stelt dat als ooit iemand precies ontdekt waar het universum voor is en waarom het er is, het onmiddellijk zal verdwijnen en worden vervangen door iets dat nog bizarder en onverklaarbaarder is. Er is een andere theorie die stelt dat dit al is gebeurd.', 'Il y a une théorie qui déclare que si jamais quelqu''un découvre exactement à quoi sert l''Univers et pourquoi il est là, il disparaîtra instantanément et sera remplacé par quelque chose d''encore plus bizarre et inexplicable. Il y a une autre théorie qui déclare que c''est déjà arrivé.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Terry Pratchett', 'The trouble with having an open mind, of course, is that people will insist on coming along and trying to put things in it.', 'Het probleem met het hebben van een open geest is natuurlijk dat mensen zullen volharden om langs te komen en er dingen in te proberen stoppen.', 'L''ennui, quand on a l''esprit ouvert, bien sûr, c''est que les gens insistent pour venir y fourrer des choses.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Terry Pratchett', 'Light thinks it travels faster than anything but it is wrong. No matter how fast light travels, it finds the darkness has always got there first, and is waiting for it.', 'Licht denkt dat het sneller reist dan wat dan ook, maar het heeft het mis. Hoe snel licht ook reist, het ontdekt dat de duisternis er altijd als eerste is aangekomen en erop wacht.', 'La lumière pense qu''elle voyage plus vite que tout, mais elle a tort. Peu importe la vitesse à laquelle la lumière voyage, elle découvre que l''obscurité est toujours arrivée la première et l''attend.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Terry Pratchett', 'Give a man a fire and he''s warm for a day, but set fire to him and he''s warm for the rest of his life.', 'Geef een man een vuur en hij heeft het een dag warm, maar steek hem in brand en hij heeft het warm voor de rest van zijn leven.', 'Donnez un feu à un homme et il aura chaud pour un jour, mais mettez le feu à un homme et il aura chaud pour le reste de sa vie.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Terry Pratchett', 'Sometimes glass glitters more than diamonds because it has more to prove.', 'Soms schittert glas meer dan diamanten omdat het meer te bewijzen heeft.', 'Parfois le verre brille plus que les diamants parce qu''il a plus à prouver.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Terry Pratchett', 'It is said that your life flashes before your eyes just before you die. That is true, it''s called Life.', 'Er wordt gezegd dat je leven aan je voorbijflitst net voordat je sterft. Dat is waar, het heet Leven.', 'On dit que votre vie défile devant vos yeux juste avant de mourir. C''est vrai, cela s''appelle la Vie.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Terry Pratchett', 'In the beginning there was nothing, which exploded.', 'In het begin was er niets, en dat ontplofte.', 'Au commencement, il n''y avait rien, et puis ça a explosé.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Terry Pratchett', 'Time is a drug. Too much of it kills you.', 'Tijd is een drug. Te veel ervan vermoordt je.', 'Le temps est une drogue. Trop de temps vous tue.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('J.R.R. Tolkien', 'I wish it need not have happened in my time, said Frodo. So do I, said Gandalf, and so do all who live to see such times. But that is not for them to decide. All we have to decide is what to do with the time that is given us.', 'Ik wilde dat het niet in mijn tijd was gebeurd, zei Frodo. Ik ook, zei Gandalf, en dat geldt voor iedereen die zulke tijden meemaakt. Maar het is niet aan hen om dat te beslissen. Het enige dat wij hoeven te beslissen, is wat we doen met de tijd die ons is gegeven.', 'Je voudrais que cela ne se fût pas passé de mon temps, dit Frodon. Moi aussi, dit Gandalf, comme tous ceux qui vivent pour voir des temps pareils. Mais la décision ne leur appartient pas. Tout ce que nous avons à décider, c''est ce qu''il faut faire du temps qui nous est imparti.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('J.R.R. Tolkien', 'All that is gold does not glitter, Not all those who wander are lost; The old that is strong does not wither, Deep roots are not reached by the frost.', 'Niet al wat goud is blinkt, Niet allen die zwerven zijn verloren; Het oude dat sterk is verwelkt niet, Diepe wortels worden niet bereikt door de vorst.', 'Tout ce qui est or ne brille pas, Tous ceux qui errent ne sont pas perdus ; Le vieux qui est fort ne se flétrit point, Les racines profondes ne sont pas atteintes par le gel.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('J.K. Rowling', 'It does not do to dwell on dreams and forget to live.', 'Het is niet goed om in dromen te blijven hangen en te vergeten te leven.', 'Il ne fait pas bon s''attarder sur les rêves et oublier de vivre.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('J.K. Rowling', 'Of course it is happening inside your head, Harry, but why on earth should that mean that it is not real?', 'Natuurlijk gebeurt het in je hoofd, Harry, maar waarom zou dat in vredesnaam betekenen dat het niet echt is?', 'Bien sûr que ça se passe dans ta tête, Harry, mais pourquoi diable cela signifierait-il que ce n''est pas réel ?', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('George R.R. Martin', 'Never forget what you are, for surely the world will not. Make it your strength. Then it can never be your weakness. Armour yourself in it, and it will never be used to hurt you.', 'Vergeet nooit wat je bent, want de wereld zal het zeker niet vergeten. Maak er je kracht van. Dan kan het nooit je zwakte zijn. Pantser jezelf erin, en het zal nooit worden gebruikt om je te kwetsen.', 'N''oublie jamais ce que tu es, car le monde ne l''oubliera certainement pas. Fais-en ta force. Ainsi, ce ne pourra jamais être ta faiblesse. Arme-toi de cela, et on ne s''en servira jamais pour te blesser.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('George R.R. Martin', 'A reader lives a thousand lives before he dies, said Jojen. The man who never reads lives only one.', 'Een lezer leeft duizend levens voordat hij sterft, zei Jojen. De man die nooit leest, leeft er maar één.', 'Un lecteur vit un millier de vies avant de mourir, dit Jojen. L''homme qui ne lit jamais n''en vit qu''une.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Ursula K. Le Guin', 'To light a candle is to cast a shadow.', 'Een kaars aansteken is een schaduw werpen.', 'Allumer une bougie, c''est projeter une ombre.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Ursula K. Le Guin', 'Light is the left hand of darkness and darkness the right hand of light. Two are one, life and death, lying together like lovers in kemmer, like hands joined together, like the end and the way.', 'Licht is de linkerhand van de duisternis en de duisternis de rechterhand van het licht. Twee zijn één, leven en dood, samenliggend als minnaars in kemmer, als samengevouwen handen, als het doel en de weg.', 'La lumière est la main gauche de l''obscurité, et l''obscurité la main droite de la lumière. Les deux ne font qu''un, la vie et la mort, enlacés comme des amants en kemmer, comme des mains jointes, comme la fin et le chemin.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Neil Gaiman', 'Fairy tales are more than true: not because they tell us that dragons exist, but because they tell us that dragons can be beaten.', 'Sprookjes zijn meer dan waar: niet omdat ze ons vertellen dat draken bestaan, maar omdat ze ons vertellen dat draken verslagen kunnen worden.', 'Les contes de fées sont plus que vrais : non parce qu''ils nous disent que les dragons existent, mais parce qu''ils nous disent que les dragons peuvent être vaincus.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Albert Camus', 'There is but one truly serious philosophical problem, and that is suicide. Judging whether life is or is not worth living amounts to answering the fundamental question of philosophy.', 'Er is maar één werkelijk serieus filosofisch probleem, en dat is zelfmoord. Oordelen of het leven wel of niet de moeite waard is om geleefd te worden, komt neer op het beantwoorden van de fundamentele vraag van de filosofie.', 'Il n''y a qu''un problème philosophique vraiment sérieux : c''est le suicide. Juger que la vie vaut ou ne vaut pas la peine d''être vécue, c''est répondre à la question fondamentale de la philosophie.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Albert Camus', 'In the midst of winter, I found there was, within me, an invincible summer.', 'Midden in de winter ontdekte ik dat er in mij een onoverwinnelijke zomer was.', 'Au milieu de l''hiver, j''apprenais enfin qu''il y avait en moi un été invincible.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Albert Camus', 'Man is the only creature who refuses to be what he is.', 'De mens is het enige schepsel dat weigert te zijn wat hij is.', 'L''homme est la seule créature qui refuse d''être ce qu''elle est.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Jean-Paul Sartre', 'All those eyes intent on me. Devouring me. What? Only two of you? I thought there were more; many more. So this is hell. I''d never have believed it. You remember all we were told about the torture-chambers, the fire and brimstone, the ''burning marl.'' Old wives'' tales! There''s no need for red-hot pokers. Hell is—other people!', 'Al die ogen die op mij gericht zijn. Die mij verslinden. Wat? Zijn jullie maar met z''n tweeën? Ik dacht dat er meer waren; veel meer. Dus dit is de hel. Ik had het nooit geloofd. Je herinnert je alles wat ons is verteld over de martelkamers, het vuur en de zwavel, de ''brandende mergel''. Oude wijvenpraat! Er is geen behoefte aan gloeiende poken. De hel, dat zijn de anderen!', 'Tous ces regards qui me mangent... Ha, vous n''êtes que deux ? Je vous croyais beaucoup plus nombreuses. Alors, c''est ça l''enfer. Je n''aurais jamais cru... Vous vous rappelez : le soufre, le bûcher, le gril... Ah ! quelle plaisanterie. Pas besoin de gril : l''enfer, c''est les Autres.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Jean-Paul Sartre', 'Man is condemned to be free; because once thrown into the world, he is responsible for everything he does.', 'De mens is veroordeeld om vrij te zijn; want eenmaal in de wereld geworpen, is hij verantwoordelijk voor alles wat hij doet.', 'L''homme est condamné à être libre ; parce qu''une fois jeté dans le monde, il est responsable de tout ce qu''il fait.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Friedrich Nietzsche', 'Beware that, when fighting monsters, you yourself do not become a monster... for when you gaze long into the abyss. The abyss gazes also into you.', 'Wie met monsters vecht, moet oppassen dat hij daarbij niet zelf een monster wordt... en als je lang in een afgrond kijkt, kijkt de afgrond ook in jou.', 'Celui qui combat des monstres doit prendre garde de ne pas devenir monstre lui-même... Et quand tu regardes longtemps dans un abîme, l''abîme regarde aussi en toi.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Friedrich Nietzsche', 'He who has a why to live for can bear almost any how.', 'Wie een waarom heeft om voor te leven, kan bijna elke hoe verdragen.', 'Celui qui a un pourquoi qui lui tient lieu de but peut vivre avec n''importe quel comment.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Friedrich Nietzsche', 'There is always some madness in love. But there is also always some reason in madness.', 'Er is altijd wat waanzin in de liefde. Maar er is ook altijd wat reden in de waanzin.', 'Il y a toujours un peu de folie dans l''amour. Mais il y a toujours aussi un peu de raison dans la folie.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Søren Kierkegaard', 'I see it all perfectly; there are two possible situations - one can either do this or that. My honest opinion and my friendly advice is this: do it or do not do it - you will regret both.', 'Ik zie het allemaal volkomen duidelijk; er zijn twee mogelijke situaties - men kan dit doen of dat. Mijn eerlijke mening en mijn vriendschappelijke advies is dit: doe het of doe het niet - je zult van beide spijt krijgen.', 'Je vois tout parfaitement ; il y a deux situations possibles - on peut faire ceci ou cela. Mon opinion honnête et mon conseil amical sont les suivants : faites-le ou ne le faites pas - vous regretterez les deux.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Søren Kierkegaard', 'Life can only be understood backwards; but it must be lived forwards.', 'Het leven kan alleen achterwaarts begrepen worden; maar het moet voorwaarts geleefd worden.', 'La vie ne peut être comprise qu''en regardant en arrière ; mais elle doit être vécue en regardant en avant.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Marcus Aurelius', 'Think of yourself as dead. You have lived your life. Now take what''s left and live it properly. Does the light of a lamp shine and keep its glow until its fuel is spent? Why shouldn''t your truth, justice, and self-control shine until you are extinguished?', 'Beschouw jezelf als dood. Je hebt je leven geleefd. Neem nu wat er over is en leef het op de juiste manier. Schijnt het licht van een lamp en behoudt het zijn gloed totdat de brandstof op is? Waarom zouden jouw waarheid, rechtvaardigheid en zelfbeheersing niet schijnen totdat jij gedoofd bent?', 'Considère-toi comme mort. Tu as achevé ta vie. Maintenant, prends ce qui te reste à vivre et vis-le selon la nature. La lumière d''une lampe brille et garde son éclat jusqu''à ce que son huile soit épuisée. Pourquoi ta vérité, ta justice et ta maîtrise de toi-même ne brilleraient-elles pas jusqu''à ce que tu sois éteint ?', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Marcus Aurelius', 'You have power over your mind - not outside events. Realize this, and you will find strength.', 'Je hebt macht over je eigen geest - niet over gebeurtenissen buitenaf. Besef dit, en je zult kracht vinden.', 'Tu as du pouvoir sur ton esprit - pas sur les événements extérieurs. Réalise cela, et tu trouveras la force.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Seneca', 'It is not that we have a short time to live, but that we waste a lot of it. Life is long enough, and a sufficiently generous amount has been given to us for the highest achievements if it were all well invested. But when it is wasted in heedless luxury and spent on no good activity, we are forced at last by death''s final constraint to realize that it has passed away before we knew it was passing.', 'Het is niet zo dat we een korte tijd te leven hebben, maar dat we er veel van verspillen. Het leven is lang genoeg, en er is ons een voldoende genereuze hoeveelheid gegeven voor de hoogste prestaties, als het maar goed werd geïnvesteerd. Maar wanneer het wordt verspild aan achteloze luxe en aan geen enkele goede activiteit wordt besteed, worden we uiteindelijk door de laatste dwang van de dood gedwongen te beseffen dat het is verstreken voordat we beseften dat het voorbijging.', 'Ce n''est pas que nous ayons peu de temps à vivre, mais que nous en perdons beaucoup. La vie est assez longue, et elle nous a été donnée avec assez de largesse pour l''accomplissement des plus grandes choses, si elle était tout entière bien placée. Mais quand elle se dissipe dans le luxe et l''indifférence, quand on ne l''emploie à rien de bon, contraints enfin par la dernière nécessité, nous nous apercevons qu''elle a passé, sans avoir compris qu''elle passait.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Seneca', 'We suffer more often in imagination than in reality.', 'We lijden vaker in onze verbeelding dan in de werkelijkheid.', 'Nous souffrons plus souvent en imagination qu''en réalité.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Epictetus', 'Men are disturbed not by things, but by the view which they take of them.', 'Mensen raken niet van streek door de dingen zelf, maar door de manier waarop ze ernaar kijken.', 'Ce ne sont pas les choses qui troublent les hommes, mais l''opinion qu''ils en ont.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Fyodor Dostoevsky', 'The mystery of human existence lies not in just staying alive, but in finding something to live for. Without a clear idea of what to live for man will not consent to live and will rather destroy himself than remain on earth, though he were surrounded by bread.', 'Het mysterie van het menselijk bestaan ligt niet in het louter in leven blijven, maar in het vinden van iets om voor te leven. Zonder een duidelijk idee van waarvoor hij moet leven, zal de mens niet instemmen te leven en zal hij zichzelf eerder vernietigen dan op aarde te blijven, zelfs al werd hij omringd door brood.', 'Le secret de l''existence humaine ne consiste pas seulement à vivre, mais à trouver un motif de vivre. Sans une idée claire du but de son existence, l''homme ne consentira jamais à vivre, et il s''anéantira plutôt que de rester sur la terre, quand bien même il serait entouré de montagnes de pain.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Fyodor Dostoevsky', 'To care only for well-being seems to me positively ill-bred. Whether it''s good or bad, it is sometimes very pleasant, too, to smash things.', 'Alleen om welzijn geven lijkt me ronduit onbeleefd. Of het nu goed of slecht is, het is soms ook heel aangenaam om dingen kapot te slaan.', 'Ne se soucier que du bien-être me semble carrément mal élevé. Que ce soit bon ou mauvais, il est parfois très agréable aussi de casser des choses.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Leo Tolstoy', 'He stepped down, trying not to look long at her, as if she were the sun, yet he saw her, like the sun, even without looking. If you look for perfection, you''ll never be content.', 'Hij stapte naar beneden en probeerde niet lang naar haar te kijken, alsof ze de zon was, maar toch zag hij haar, net als de zon, zelfs zonder te kijken. Als je naar perfectie zoekt, zul je nooit tevreden zijn.', 'Il descendit, en s''efforçant de ne pas la regarder longuement, comme on évite de regarder le soleil, mais il la voyait, comme le soleil, même sans la regarder. Si vous cherchez la perfection, vous ne serez jamais satisfait.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Leo Tolstoy', 'We can know only that we know nothing. And that is the highest degree of human wisdom.', 'We kunnen alleen weten dat we niets weten. En dat is de hoogste graad van menselijke wijsheid.', 'Nous ne pouvons savoir qu''une chose, c''est que nous ne savons rien. Et c''est là le plus haut degré de la sagesse humaine.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Mary Shelley', 'Learn from me, if not by my precepts, at least by my example, how dangerous is the acquirement of knowledge and how much happier that man is who believes his native town to be the world, than he who aspires to become greater than his nature will allow.', 'Leer van mij, is het niet door mijn voorschriften, dan op z''n minst door mijn voorbeeld, hoe gevaarlijk de verwerving van kennis is, en hoeveel gelukkiger de mens is die gelooft dat zijn geboortestad de wereld is, dan hij die ernaar streeft groter te worden dan zijn natuur toestaat.', 'Apprenez de moi, sinon par mes préceptes, du moins par mon exemple, combien l''acquisition du savoir est dangereuse, et combien est plus heureux l''homme qui croit que sa ville natale est le monde entier, que celui qui aspire à devenir plus grand que sa nature ne le permet.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Victor Hugo', 'To love or have loved, that is enough. Ask nothing further. There is no other pearl to be found in the dark folds of life.', 'Liefhebben of liefgehad hebben, dat is genoeg. Vraag niets meer. Er is geen andere parel te vinden in de donkere plooien van het leven.', 'Aimer ou avoir aimé, cela suffit. Ne demandez rien d''autre. Il n''y a pas d''autre perle à trouver dans les plis ténébreux de la vie.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Victor Hugo', 'He who does not read, has no advantage over him who cannot read.', 'Hij die niet leest, heeft geen voordeel ten opzichte van hem die niet kan lezen.', 'Celui qui ne lit pas n''a aucun avantage sur celui qui ne sait pas lire.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Alexandre Dumas', 'All human wisdom is contained in these two words - Wait and Hope.', 'Alle menselijke wijsheid is vervat in deze twee woorden: Wachten en Hopen.', 'Toute la sagesse humaine sera dans ces deux mots : Attendre et Espérer.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Oscar Wilde', 'We are all in the gutter, but some of us are looking at the stars.', 'We liggen allemaal in de goot, maar sommigen van ons kijken naar de sterren.', 'Nous sommes tous dans le caniveau, mais certains d''entre nous regardent les étoiles.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Oscar Wilde', 'The only way to get rid of a temptation is to yield to it. Resist it, and your soul grows sick with longing for the things it has forbidden to itself.', 'De enige manier om van een verleidinging af te komen, is eraan toegeven. Verzet je ertegen, en je ziel wordt ziek van verlangen naar de dingen die ze zichzelf heeft verboden.', 'Le seul moyen de se délivrer d''une tentation, c''est d''y céder. Résistez et votre âme se rend malade à force de languir ce qu''elle s''est interdit.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Virginia Woolf', 'Lock up your libraries if you like; but there is no gate, no lock, no bolt that you can set upon the freedom of my mind.', 'Sluit je bibliotheken maar af als je wilt; maar er is geen poort, geen slot, geen grendel die je kunt plaatsen op de vrijheid van mijn geest.', 'Fermez vos bibliothèques si vous voulez ; mais il n''y a pas de porte, pas de serrure, pas de verrou que vous puissiez mettre sur la liberté de mon esprit.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Franz Kafka', 'I am a cage, in search of a bird.', 'Ik ben een kooi, op zoek naar een vogel.', 'Je suis une cage, en quête d''un oiseau.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Herman Melville', 'I know not all that may be coming, but be it what it will, I''ll go to it laughing.', 'Ik weet niet alles wat er komen gaat, maar wat het ook is, ik zal er lachend naartoe gaan.', 'Je ne sais pas tout ce qui peut arriver, mais quoi qu''il en soit, j''y irai en riant.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Sylvia Plath', 'I took a deep breath and listened to the old brag of my heart. I am, I am, I am.', 'Ik haalde diep adem en luisterde naar de oude opschepperij van mijn hart. Ik ben, ik ben, ik ben.', 'J''ai pris une grande inspiration et j''ai écouté la vieille vantardise de mon cœur. Je suis, je suis, je suis.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Frank Herbert', 'I must not fear. Fear is the mind-killer. Fear is the little-death that brings total obliteration. I will face my fear. I will permit it to pass over me and through me. And when it has gone past I will turn the inner eye to see its path. Where the fear has gone there will be nothing. Only I will remain.', 'Ik mag niet vrezen. Angst is de geestendoder. Angst is de kleine dood die totale vernietiging brengt. Ik zal mijn angst onder ogen zien. Ik zal het over mij en door mij heen laten trekken. En als het voorbij is, zal ik het innerlijke oog richten om het pad ervan te zien. Waar de angst is gegaan, zal niets meer zijn. Alleen ik zal overblijven.', 'Je ne dois pas avoir peur. La peur tue l''esprit. La peur est la petite mort qui conduit à l''oblitération totale. J''affronterai ma peur. Je lui permettrai de passer sur moi, au travers de moi. Et lorsqu''elle sera passée, je tournerai mon œil intérieur sur son chemin. Et là où la peur sera passée, il n''y aura plus rien. Rien que moi.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Frank Herbert', 'The mystery of life isn''t a problem to solve, but a reality to experience.', 'Het mysterie van het leven is geen probleem om op te lossen, maar een realiteit om te ervaren.', 'Le mystère de la vie n''est pas un problème à résoudre, mais une réalité à expérimenter.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Kurt Vonnegut', 'And I asked myself about the present: how wide it was, how deep it was, how much was mine to keep.', 'En ik vroeg me af over het heden: hoe breed het was, hoe diep het was, en hoeveel ervan ik mocht houden.', 'Et je m''interrogeais sur le présent : quelle était sa largeur, quelle était sa profondeur, quelle part m''appartenait pour toujours.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Kurt Vonnegut', 'We are what we pretend to be, so we must be careful about what we pretend to be.', 'We zijn wat we doen alsof we zijn, dus we moeten voorzichtig zijn met wat we doen alsof we zijn.', 'Nous sommes ce que nous prétendons être, nous devons donc faire attention à ce que nous prétendons être.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Isaac Asimov', 'Violence is the last refuge of the incompetent.', 'Geweld is het laatste toevluchtsoord van de incompetenten.', 'La violence est le dernier refuge de l''incompétence.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Isaac Asimov', 'Never let your sense of morals prevent you from doing what is right.', 'Laat je gevoel voor moraal je er nooit van weerhouden te doen wat juist is.', 'Ne laissez jamais votre sens de la morale vous empêcher de faire ce qui est juste.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Philip K. Dick', 'Reality is that which, when you stop believing in it, doesn''t go away.', 'De realiteit is datgene wat niet weggaat als je er niet meer in gelooft.', 'La réalité, c''est ce qui continue d''exister lorsqu''on cesse d''y croire.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('William Gibson', 'The sky above the port was the color of television, tuned to a dead channel.', 'De lucht boven de haven had de kleur van een televisie die op een dood kanaal was afgestemd.', 'Le ciel au-dessus du port était de la couleur d''une télévision allumée sur une chaîne morte.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Ray Bradbury', 'You don''t have to burn books to destroy a culture. Just get people to stop reading them.', 'Je hoeft geen boeken te verbranden om een cultuur te vernietigen. Zorg er gewoon voor dat mensen ze niet meer lezen.', 'Vous n''avez pas besoin de brûler des livres pour détruire une culture. Il suffit de faire en sorte que les gens arrêtent de les lire.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Arthur C. Clarke', 'Any sufficiently advanced technology is indistinguishable from magic.', 'Elke voldoende geavanceerde technologie is niet te onderscheiden van magie.', 'Toute technologie suffisamment avancée est indiscernable de la magie.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Arthur C. Clarke', 'The only way of discovering the limits of the possible is to venture a little way past them into the impossible.', 'De enige manier om de grenzen van het mogelijke te ontdekken, is door er een stukje voorbij te wagen, het onmogelijke in.', 'La seule façon de découvrir les limites du possible est de s''aventurer un peu au-delà, dans l''impossible.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('H.G. Wells', 'Nature never appeals to intelligence until habit and instinct are useless. There is no intelligence where there is no change and no need of change.', 'De natuur doet nooit een beroep op intelligentie totdat gewoonte en instinct nutteloos zijn. Er is geen intelligentie waar geen verandering is en geen behoefte aan verandering.', 'La nature ne fait jamais appel à l''intelligence tant que l''habitude et l''instinct ne sont pas inutiles. Il n''y a pas d''intelligence là où il n''y a ni changement ni besoin de changement.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Aldous Huxley', 'Words can be like X-rays if you use them properly -- they''ll go through anything. You read and you''re pierced.', 'Woorden kunnen als röntgenstralen zijn als je ze goed gebruikt -- ze gaan overal doorheen. Je leest en je wordt doorboord.', 'Les mots peuvent être comme des rayons X si on s''en sert convenablement -- ils transpercent n''importe quoi. Vous lisez, et vous êtes transpercé.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('George Orwell', 'It was a bright cold day in April, and the clocks were striking thirteen.', 'Het was een heldere, koude dag in april en de klokken sloegen dertien.', 'C''était une journée d''avril froide et claire, et les horloges sonnaient treize heures.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('George Orwell', 'If you want a picture of the future, imagine a boot stamping on a human face—for ever.', 'Als je een beeld van de toekomst wilt, stel je dan een laars voor die op een menselijk gezicht stampt - voor altijd.', 'Si vous voulez une image de l''avenir, imaginez une botte piétinant un visage humain, éternellement.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Carl Sagan', 'Look again at that dot. That''s here. That''s home. That''s us. On it everyone you love, everyone you know, everyone you ever heard of, every human being who ever was, lived out their lives. The aggregate of our joy and suffering... lived there—on a mote of dust suspended in a sunbeam.', 'Kijk nog eens naar die stip. Dat is hier. Dat is thuis. Dat zijn wij. Daarop heeft iedereen van wie je houdt, iedereen die je kent, iedereen van wie je ooit hebt gehoord, ieder mens die ooit heeft bestaan, zijn of haar leven geleefd. Het totaal van onze vreugde en ons lijden... leefde daar — op een stofje dat zweeft in een zonnestraal.', 'Regardez encore ce petit point. C''est ici. C''est notre foyer. C''est nous. Sur lui se trouvent tous ceux que vous aimez, tous ceux que vous connaissez, tous ceux dont vous avez entendu parler, tous les êtres humains qui aient jamais vécu. La somme de nos joies et de nos souffrances... a vécu là — sur un grain de poussière suspendu dans un rayon de soleil.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Carl Sagan', 'We are a way for the cosmos to know itself.', 'Wij zijn een manier voor de kosmos om zichzelf te kennen.', 'Nous sommes un moyen pour le cosmos de se connaître lui-même.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Carl Sagan', 'Somewhere, something incredible is waiting to be known.', 'Ergens wacht iets ongelooflijks om gekend te worden.', 'Quelque part, quelque chose d''incroyable attend d''être connu.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Albert Einstein', 'Two things are infinite: the universe and human stupidity; and I''m not sure about the universe.', 'Twee dingen zijn oneindig: het universum en menselijke domheid; en van het universum weet ik het niet zeker.', 'Deux choses sont infinies : l''Univers et la bêtise humaine. Mais, en ce qui concerne l''Univers, je n''en ai pas encore acquis la certitude absolue.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Stephen Hawking', 'I have noticed even people who claim everything is predestined, and that we can do nothing to change it, look before they cross the road.', 'Ik heb gemerkt dat zelfs mensen die beweren dat alles is voorbestemd en dat we niets kunnen doen om het te veranderen, uitkijken voordat ze de weg oversteken.', 'J''ai remarqué que même les gens qui affirment que tout est prédestiné et que nous ne pouvons rien faire pour le changer regardent avant de traverser la route.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Mark Twain', 'You can''t depend on your eyes when your imagination is out of focus.', 'Je kunt niet op je ogen vertrouwen als je verbeelding onscherp is.', 'Vous ne pouvez pas dépendre de vos yeux lorsque votre imagination est floue.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Mark Twain', 'The two most important days in your life are the day you are born and the day you find out why.', 'De twee belangrijkste dagen in je leven zijn de dag dat je geboren wordt en de dag dat je erachter komt waarom.', 'Les deux jours les plus importants de votre vie sont le jour où vous êtes né et le jour où vous découvrez pourquoi.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Haruki Murakami', 'Memories warm you up from the inside. But they also tear you apart.', 'Herinneringen verwarmen je van binnenuit. Maar ze verscheuren je ook.', 'Les souvenirs vous réchauffent de l''intérieur. Mais ils vous déchirent aussi.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Jorge Luis Borges', 'I have always imagined that Paradise will be a kind of library.', 'Ik heb me altijd voorgesteld dat het Paradijs een soort bibliotheek zal zijn.', 'J''ai toujours imaginé que le Paradis serait une sorte de bibliothèque.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Anaïs Nin', 'We do not see things as they are, we see them as we are.', 'We zien de dingen niet zoals ze zijn, we zien ze zoals wij zijn.', 'Nous ne voyons pas les choses telles qu''elles sont, nous les voyons telles que nous sommes.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Herman Melville', 'Call me Ishmael.', 'Noem me Ismaël.', 'Appelez-moi Ismaël.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Charles Dickens', 'It was the best of times, it was the worst of times.', 'Het was de beste der tijden, het was de slechtste der tijden.', 'C''était le meilleur des temps, c''était le pire des temps.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Jane Austen', 'It is a truth universally acknowledged, that a single man in possession of a good fortune, must be in want of a wife.', 'Het is een algemeen erkende waarheid dat een alleenstaande man in het bezit van een goed fortuin, behoefte moet hebben aan een vrouw.', 'C''est une vérité universellement reconnue qu''un célibataire pourvu d''une belle fortune doit avoir envie de se marier.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('F. Scott Fitzgerald', 'So we beat on, boats against the current, borne back ceaselessly into the past.', 'Zo varen we voort, boten tegen de stroom in, onophoudelijk teruggevoerd naar het verleden.', 'Car nous luttons ainsi, barques à contre-courant, refoulés sans fin vers notre passé.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Ralph Waldo Emerson', 'To be yourself in a world that is constantly trying to make you something else is the greatest accomplishment.', 'Jezelf zijn in een wereld die voortdurend probeert iets anders van je te maken, is de grootste prestatie.', 'Être soi-même dans un monde qui tente constamment de faire de vous quelqu''un d''autre est le plus grand accomplissement.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Lao Tzu', 'The journey of a thousand miles begins with one step.', 'De reis van duizend mijl begint met één stap.', 'Un voyage de mille lieues commence toujours par un premier pas.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Confucius', 'Every man has two lives, and the second starts when he realizes he has just one.', 'Ieder mens heeft twee levens, en de tweede begint wanneer hij beseft dat hij er maar één heeft.', 'On a deux vies, et la seconde commence quand on se rend compte qu''on n''en a qu''une.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Rumi', 'What you seek is seeking you.', 'Wat je zoekt, zoekt jou.', 'Ce que tu cherches te cherche.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Rumi', 'The wound is the place where the Light enters you.', 'De wond is de plek waar het Licht naar binnen komt.', 'La blessure est l''endroit par où la lumière entre en vous.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('John Lennon', 'Life is what happens to you while you''re busy making other plans.', 'Het leven is wat je overkomt terwijl je druk bent met het maken van andere plannen.', 'La vie, c''est ce qui arrive quand on a d''autres projets.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Dr. Seuss', 'Don''t cry because it''s over, smile because it happened.', 'Huil niet omdat het voorbij is, glimlach omdat het is gebeurd.', 'Ne pleure pas parce que c''est fini, souris parce que c''est arrivé.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Robert Frost', 'In three words I can sum up everything I''ve learned about life: it goes on.', 'In drie woorden kan ik alles samenvatten wat ik over het leven heb geleerd: het gaat door.', 'En trois mots, je peux résumer tout ce que j''ai appris sur la vie : elle continue.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Mahatma Gandhi', 'Darkness cannot drive out darkness: only light can do that. Hate cannot drive out hate: only love can do that.', 'Duisternis kan duisternis niet verdrijven: dat kan alleen het licht. Haat kan haat niet verdrijven: dat kan alleen de liefde.', 'L''obscurité ne peut pas chasser l''obscurité : seule la lumière peut faire cela. La haine ne peut pas chasser la haine : seul l''amour peut faire cela.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Martin Luther King Jr.', 'In the end, we will remember not the words of our enemies, but the silence of our friends.', 'Uiteindelijk zullen we ons niet de woorden van onze vijanden herinneren, maar het zwijgen van onze vrienden.', 'À la fin, nous ne nous souviendrons pas des mots de nos ennemis, mais du silence de nos amis.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Winston Churchill', 'Success is not final, failure is not fatal: it is the courage to continue that counts.', 'Succes is niet definitief, falen is niet fataal: het is de moed om door te gaan die telt.', 'Le succès n''est pas final, l''échec n''est pas fatal : c''est le courage de continuer qui compte.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Eleanor Roosevelt', 'No one can make you feel inferior without your consent.', 'Niemand kan je een minderwaardigheidsgevoel geven zonder jouw toestemming.', 'Personne ne peut vous faire sentir inférieur sans votre consentement.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Maya Angelou', 'There is no greater agony than bearing an untold story inside you.', 'Er is geen grotere kwelling dan een onverteld verhaal in je te dragen.', 'Il n''y a pas de plus grande agonie que de porter une histoire non racontée à l''intérieur de soi.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('C.S. Lewis', 'To love at all is to be vulnerable.', 'Liefhebben is kwetsbaar zijn.', 'Aimer, c''est être vulnérable.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('C.S. Lewis', 'One day, you will be old enough to start reading fairytales again.', 'Op een dag zul je oud genoeg zijn om weer sprookjes te gaan lezen.', 'Un jour, tu seras assez vieux pour recommencer à lire des contes de fées.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('J.M. Barrie', 'To die will be an awfully big adventure.', 'Sterven zal een ontzettend groot avontuur zijn.', 'Mourir sera une aventure terriblement grande.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Stephen King', 'The man in black fled across the desert, and the gunslinger followed.', 'De man in het zwart vluchtte door de woestijn, en de scherpschutter volgde hem.', 'L''homme en noir fuyait à travers le désert, et le pistolero le suivait.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Antoine de Saint-Exupéry', 'It is only with the heart that one can see rightly; what is essential is invisible to the eye.', 'Alleen met het hart kun je goed zien; wat essentieel is, is onzichtbaar voor het oog.', 'On ne voit bien qu''avec le cœur. L''essentiel est invisible pour les yeux.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Hermann Hesse', 'Some of us think holding on makes us strong; but sometimes it is letting go.', 'Sommigen van ons denken dat vasthouden ons sterk maakt; maar soms is het loslaten.', 'Certains d''entre nous pensent que s''accrocher nous rend forts ; mais parfois, c''est lâcher prise.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Sylvia Plath', 'Let me live, love, and say it well in good sentences.', 'Laat me leven, liefhebben en het goed zeggen in mooie zinnen.', 'Laisse-moi vivre, aimer, et le dire bien en de belles phrases.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Roald Dahl', 'Those who don''t believe in magic will never find it.', 'Zij die niet in magie geloven, zullen het nooit vinden.', 'Ceux qui ne croient pas en la magie ne la trouveront jamais.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Charles Bukowski', 'Find what you love and let it kill you.', 'Vind wat je liefhebt en laat het je vermoorden.', 'Trouve ce que tu aimes et laisse-le te tuer.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Jack Kerouac', 'Nothing behind me, everything ahead of me, as is ever so on the road.', 'Niets achter me, alles voor me, zoals altijd onderweg.', 'Rien derrière moi, tout devant moi, comme toujours sur la route.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Hunter S. Thompson', 'We are all alone, born alone, die alone, and—in spite of True Romance magazines—we shall all someday look back on our lives and see that, in spite of our company, we were alone the whole way.', 'We zijn allemaal alleen, worden alleen geboren, sterven alleen, en—ondanks tijdschriften over ware liefde—zullen we ooit terugkijken op ons leven en zien dat we, ondanks ons gezelschap, de hele weg alleen waren.', 'Nous sommes tous seuls, nés seuls, mourons seuls, et - en dépit des magazines True Romance - nous regarderons tous un jour notre vie et verrons que, malgré notre compagnie, nous étions seuls tout le long du chemin.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Ralph Ellison', 'I am invisible, understand, simply because people refuse to see me.', 'Ik ben onzichtbaar, begrijp je, simpelweg omdat mensen weigeren mij te zien.', 'Je suis invisible, comprenez-le, simplement parce que les gens refusent de me voir.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Zora Neale Hurston', 'There are years that ask questions and years that answer.', 'Er zijn jaren die vragen stellen en jaren die antwoorden.', 'Il y a des années qui posent des questions et des années qui répondent.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Gabriel García Márquez', 'What matters in life is not what happens to you but what you remember and how you remember it.', 'Wat er in het leven toe doet, is niet wat je overkomt, maar wat je je herinnert en hoe je het je herinnert.', 'Ce qui compte dans la vie, ce n''est pas ce qui vous arrive, mais ce dont vous vous souvenez et comment vous vous en souvenez.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Milan Kundera', 'If you only read the books that everyone else is reading, you can only think what everyone else is thinking.', 'Als je alleen de boeken leest die alle anderen lezen, kun je alleen maar denken wat alle anderen denken.', 'Si vous ne lisez que les livres que tout le monde lit, vous ne pouvez penser que ce que tout le monde pense.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Italo Calvino', 'A single metaphor can give birth to love.', 'Een enkele metafoor kan de liefde doen ontwaken.', 'Une seule métaphore peut donner naissance à l''amour.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Umberto Eco', 'You take delight not in a city''s seven or seventy wonders, but in the answer it gives to a question of yours.', 'Je geniet niet van de zeven of zeventig wonderen van een stad, maar van het antwoord dat ze geeft op een vraag van jou.', 'Vous ne prenez pas plaisir aux sept ou soixante-dix merveilles d''une ville, mais à la réponse qu''elle donne à l''une de vos questions.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Margaret Atwood', 'Nolite te bastardes carborundorum.', 'Nolite te bastardes carborundorum.', 'Nolite te bastardes carborundorum.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Neil Gaiman', 'Things need not have happened to be true. Tales and dreams are the shadow-truths that will endure when mere facts are dust and ashes, and forgot.', 'Dingen hoeven niet gebeurd te zijn om waar te zijn. Verhalen en dromen zijn de schaduwwaarheden die zullen voortbestaan wanneer louter feiten stof en as zijn, en vergeten.', 'Les choses n''ont pas besoin de s''être produites pour être vraies. Les contes et les rêves sont les vérités de l''ombre qui perdureront quand les simples faits ne seront que poussière et cendres, et oubliés.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Douglas Adams', 'I''d far rather be happy than right any day.', 'Ik ben veel liever gelukkig dan dat ik altijd gelijk heb.', 'Je préfère de loin être heureux qu''avoir raison.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Douglas Adams', 'If there''s anything more important than my ego around, I want it caught and shot now.', 'Als er iets belangrijkers in de buurt is dan mijn ego, wil ik dat het nu wordt gevangen en neergeschoten.', 'S''il y a quelque chose de plus important que mon ego dans les parages, je veux qu''on l''attrape et qu''on l''abatte tout de suite.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Terry Pratchett', 'The sheer, naked, unadulterated, pure, unalloyed, unmitigated truth is that I am completely and utterly baffled.', 'De pure, naakte, onvervalste, zuivere, onversneden, onverbloemde waarheid is dat ik volkomen verbijsterd ben.', 'La vérité pure, nue, sans mélange, sans alliage et sans circonstances atténuantes, c''est que je suis complètement et totalement perplexe.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Terry Pratchett', 'Personal''s not the same as important.', 'Persoonlijk is niet hetzelfde als belangrijk.', 'Personnel n''est pas la même chose qu''important.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('J.R.R. Tolkien', 'Never laugh at live dragons, Bilbo you fool!', 'Lach nooit om levende draken, Bilbo, dwaas!', 'Ne riez jamais des dragons vivants, Bilbo espèce d''idiot !', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('J.R.R. Tolkien', 'It is not our part to master all the tides of the world, but to do what is in us for the succour of those years wherein we are set, uprooting the evil in the fields that we know, so that those who live after may have clean earth to till.', 'Het is niet onze taak om alle getijden van de wereld te beheersen, maar om te doen wat in onze macht ligt voor de redding van de jaren waarin wij geplaatst zijn, door het kwaad uit te roeien in de velden die wij kennen, zodat zij die na ons leven schone aarde hebben om te bewerken.', 'Il ne nous appartient pas de maîtriser toutes les marées du monde, mais de faire ce qui est en nous pour secourir les années dans lesquelles nous sommes placés, en déracinant le mal dans les champs que nous connaissons, afin que ceux qui vivront après nous aient une terre propre à cultiver.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('George R.R. Martin', 'There is only one god, and His name is Death. And there is only one thing we say to Death: ''Not today''.', 'Er is maar één god, en zijn naam is de Dood. En er is maar één ding dat we tegen de Dood zeggen: ''Niet vandaag''.', 'Il n''y a qu''un seul dieu, et son nom est la Mort. Et il n''y a qu''une seule chose que nous disons à la Mort : ''Pas aujourd''hui''.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('George R.R. Martin', 'A mind needs books as a sword needs a whetstone, if it is to keep its edge.', 'Een geest heeft boeken nodig zoals een zwaard een wetsteen nodig heeft, als het scherp wil blijven.', 'L''esprit a besoin de livres comme l''épée a besoin d''une pierre à aiguiser, pour conserver son tranchant.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Ursula K. Le Guin', 'It is good to have an end to journey toward; but it is the journey that matters, in the end.', 'Het is goed om een einde te hebben om naartoe te reizen; maar het is de reis die ertoe doet, uiteindelijk.', 'Il est bon d''avoir une fin vers laquelle voyager ; mais c''est le voyage qui compte, au bout du compte.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Isaac Asimov', 'The saddest aspect of life right now is that science gathers knowledge faster than society gathers wisdom.', 'Het droevigste aspect van het leven op dit moment is dat de wetenschap sneller kennis vergaart dan de samenleving wijsheid vergaart.', 'L''aspect le plus triste de la vie en ce moment est que la science accumule les connaissances plus vite que la société n''accumule la sagesse.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Arthur C. Clarke', 'Behind every man now alive stand thirty ghosts, for that is the ratio by which the dead outnumber the living.', 'Achter elke man die nu leeft staan dertig geesten, want dat is de verhouding waarmee de doden in de meerderheid zijn over de levenden.', 'Derrière chaque homme actuellement en vie se tiennent trente fantômes, car c''est le rapport par lequel les morts sont plus nombreux que les vivants.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Philip K. Dick', 'You will be required to do wrong no matter where you go. It is the basic condition of life, to be required to violate your own identity.', 'Je zult gedwongen worden om fouten te maken, waar je ook gaat. Het is de basisvoorwaarde van het leven, gedwongen te worden je eigen identiteit te schenden.', 'On exigera de vous que vous fassiez le mal, peu importe où vous irez. C''est la condition fondamentale de la vie, d''être contraint de violer sa propre identité.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('William Gibson', 'The future is there... looking back at us. Trying to make sense of the fiction we will have become.', 'De toekomst is daar... en kijkt naar ons terug. Ze probeert de fictie te begrijpen die we zullen zijn geworden.', 'L''avenir est là... qui nous regarde en arrière. Essayant de donner un sens à la fiction que nous serons devenus.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Ray Bradbury', 'We earth men have a talent for ruining big, beautiful things.', 'Wij aardbewoners hebben een talent voor het ruïneren van grote, mooie dingen.', 'Nous, les Terriens, avons le talent de gâcher les grandes et belles choses.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Kurt Vonnegut', 'Science has now known sin.', 'De wetenschap heeft nu de zonde leren kennen.', 'La science a maintenant connu le péché.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Robert A. Heinlein', 'A generation which ignores history has no past—and no future.', 'Een generatie die de geschiedenis negeert, heeft geen verleden — en geen toekomst.', 'Une génération qui ignore l''histoire n''a pas de passé — et pas d''avenir.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Orson Scott Card', 'In the moment when I truly understand my enemy, understand him well enough to defeat him, then in that very moment I also love him.', 'Op het moment dat ik mijn vijand echt begrijp, hem goed genoeg begrijp om hem te verslaan, dan heb ik hem op datzelfde moment ook lief.', 'Au moment où je comprends vraiment mon ennemi, où je le comprends assez bien pour le vaincre, à cet instant précis, je l''aime aussi.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Neal Stephenson', 'To condense fact from the vapor of nuance.', 'Feiten condenseren uit de damp van nuance.', 'Condenser les faits à partir de la vapeur de la nuance.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Margaret Atwood', 'When any civilization is dust and ashes, art is all that''s left over. Images, words, music. Imaginative structures.', 'Wanneer een beschaving tot stof en as is vergaan, is kunst het enige dat overblijft. Beelden, woorden, muziek. Verbeeldingsrijke structuren.', 'Lorsqu''une civilisation n''est plus que poussière et cendres, l''art est tout ce qui reste. Images, mots, musique. Des structures imaginatives.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Socrates', 'I cannot teach anybody anything. I can only make them think.', 'Ik kan niemand iets leren. Ik kan ze alleen maar laten nadenken.', 'Je ne peux rien enseigner à personne. Je ne peux que les faire réfléchir.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Plato', 'Wise men speak because they have something to say; Fools because they have to say something.', 'Wijze mannen spreken omdat ze iets te zeggen hebben; dwazen omdat ze iets moeten zeggen.', 'Les sages parlent parce qu''ils ont quelque chose à dire ; les imbéciles parce qu''ils doivent dire quelque chose.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Aristotle', 'Knowing yourself is the beginning of all wisdom.', 'Jezelf kennen is het begin van alle wijsheid.', 'La connaissance de soi est le commencement de toute sagesse.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Epicurus', 'Wealth consists not in having great possessions, but in having few wants.', 'Rijkdom bestaat niet uit het hebben van grote bezittingen, maar uit het hebben van weinig behoeften.', 'La richesse ne consiste pas à avoir de grandes possessions, mais à avoir peu de désirs.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Diogenes', 'We have two ears and one tongue so that we would listen more and talk less.', 'We hebben twee oren en één tong zodat we meer zouden luisteren en minder praten.', 'Nous avons deux oreilles et une langue pour écouter plus et parler moins.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Immanuel Kant', 'Rules for happiness: something to do, someone to love, something to hope for.', 'Regels voor geluk: iets om te doen, iemand om lief te hebben, iets om op te hopen.', 'Règles pour le bonheur : quelque chose à faire, quelqu''un à aimer, quelque chose à espérer.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Rene Descartes', 'I think; therefore I am.', 'Ik denk, dus ik ben.', 'Je pense, donc je suis.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('John Locke', 'Reading furnishes the mind only with materials of knowledge; it is thinking that makes what we read ours.', 'Lezen voorziet de geest alleen van materiaal voor kennis; het is het denken dat maakt wat we lezen van ons.', 'La lecture ne fournit à l''esprit que des matériaux de connaissance ; c''est la réflexion qui fait nôtre ce que nous lisons.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Thomas Hobbes', 'Hell is truth seen too late.', 'De hel is de waarheid die te laat wordt ingezien.', 'L''enfer est la vérité vue trop tard.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Baruch Spinoza', 'Peace is not an absence of war, it is a virtue, a state of mind, a disposition for benevolence, confidence, justice.', 'Vrede is geen afwezigheid van oorlog, het is een deugd, een gemoedstoestand, een aanleg voor welwillendheid, vertrouwen, rechtvaardigheid.', 'La paix n''est pas l''absence de guerre, c''est une vertu, un état d''esprit, une disposition à la bienveillance, à la confiance, à la justice.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('David Hume', 'A wise man proportions his belief to the evidence.', 'Een wijs man stemt zijn overtuiging af op het bewijs.', 'Un homme sage proportionne sa croyance aux preuves.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Voltaire', 'Let us read, and let us dance; these two amusements will never do any harm to the world.', 'Laten we lezen, en laten we dansen; deze twee pleziertjes zullen de wereld nooit kwaad doen.', 'Lisons et dansons ; ces deux amusements ne feront jamais de mal au monde.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Jean-Jacques Rousseau', 'Man is born free, and everywhere he is in chains.', 'De mens wordt vrij geboren, en overal ligt hij in ketenen.', 'L''homme est né libre, et partout il est dans les fers.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Marie Curie', 'Nothing in life is to be feared, it is only to be understood. Now is the time to understand more, so that we may fear less.', 'Niets in het leven is om gevreesd te worden, het is alleen om begrepen te worden. Nu is het tijd om meer te begrijpen, zodat we minder hoeven te vrezen.', 'Rien dans la vie ne doit être craint, tout doit être compris. C''est le moment de comprendre davantage, afin de craindre moins.', 1, 0);
INSERT INTO quotes (author, text_en, text_nl, text_fr, weight, views) VALUES ('Charles Darwin', 'It is not the strongest of the species that survives, nor the most intelligent that survives. It is the one that is most adaptable to change.', 'Het is niet de sterkste van de soort die overleeft, noch de meest intelligente. Het is degene die zich het beste kan aanpassen aan verandering.', 'Ce n''est pas la plus forte des espèces qui survit, ni la plus intelligente. C''est celle qui est la plus adaptable au changement.', 1, 0);
